#include "harness_start.bash"

# The llvm-tblgen shape under AUTORECONFIGURE, after a "make clean":
# the header app.c reads is generated by a tool the project builds,
# and none of the tool, the header or any fragment is there any more.
# app.c's fragment has to name the header before it exists, so that
# the object waits for it -- and naming it must not drag the tool's
# link into the phase where make is still remaking fragments, before
# it has read the one that says which objects the tool is made of.
# The order this checks is the one the build without AUTORECONFIGURE
# already keeps: tool linked, header generated from it, consumer
# compiled after that.
export PATH="$(dirname "$PTEST_BINARY"):$PATH"

mkdir -p src

cat >Configfile <<EOF
AUTORECONFIGURE = true

LANGUAGES += c

BINARIES  += gen
SOURCES   += gen.c

GENERATE  += gen.h

BINARIES  += app
SOURCES   += app.c
EOF

cat >src/gen.c <<'EOF'
#include <stdio.h>
int main(void) { printf("#define ANSWER 10\n"); return 0; }
EOF

cat >src/gen.h.proc <<'EOF'
#!/bin/bash
case "$1" in
--deps)     echo "src/gen.c bin/gen" ;;
--generate) if test -x bin/gen; then bin/gen; else echo "#define ANSWER 0"; fi ;;
esac
EOF
chmod +x src/gen.h.proc

cat >src/app.c <<'EOF'
  #include "gen.h"
  #include <stdio.h>
int main(void) { printf("%d\n", ANSWER); return 0; }
EOF

$PTEST_BINARY $PCONFIGURE_ARGS
make $MAKE_ARGS
test "$(./bin/app)" = "10"

make $MAKE_ARGS clean
test ! -e bin/gen
test ! -e obj/proc/gen.h

make $MAKE_ARGS > after-clean.out 2>&1
cat after-clean.out
test "$(./bin/app)" = "10"

grep -q "^LD	gen$" after-clean.out
grep -q "^GEN	gen.h$" after-clean.out
grep -q "^CC	app.c$" after-clean.out
test "$(grep -n '^LD	gen$' after-clean.out | head -1 | cut -d: -f1)" -lt "$(grep -n '^GEN	gen.h$' after-clean.out | tail -1 | cut -d: -f1)"
test "$(grep -n '^GEN	gen.h$' after-clean.out | tail -1 | cut -d: -f1)" -lt "$(grep -n '^CC	app.c$' after-clean.out | tail -1 | cut -d: -f1)"

# And the generator's source still reaches the program.
sleep 2
printf '#include <stdio.h>\nint main(void) { printf("#define ANSWER 11\\n"); return 0; }\n' > src/gen.c
make $MAKE_ARGS
test "$(./bin/app)" = "11"

exit 0
